#!/usr/bin/env python3
"""Regenerate the tiny-ppocr ONNX fixtures (M3-T10, the OCR twin of
tiny-siglip2/generate.py — same hermetic discipline: committed artifacts
were produced by this script; rerun only when the fixture shape must
change, every test that pins recognized VALUES will need updating too).

The fixtures mirror the I/O contract of the REAL pinned artifacts
(PaddlePaddle PP-OCRv5 mobile det/rec ONNX, verified 2026-11-07 against
the actual repos):

  det  `det.onnx`
    IN  x FLOAT [1, 3, height, width]  (dynamic H/W — the real export too;
        preprocessing lives in OUR code, per its inference.yml)
    OUT a probability map FLOAT [1, 1, height, width]
    graph: ReduceMax(channel) -> *0 + 20 -> Sigmoid — a CONSTANT ~1.0 map
        (sigmoid(20) = 1 - 2e-9) in the input's shape: every page becomes
        one whole-page detection through the real DB postprocess, exactly
        the deterministic fixture contract.

  rec  `rec.onnx`
    IN  x FLOAT [1, 3, 48, width]      (dynamic width 160..3200 on the real
        export; the fixture takes any W >= 1)
    OUT FLOAT [1, T, C] with T = ceil(W/8), C = 9 — per-timestep softmaxed
        logits. graph: ReduceMax(channels+rows) -> [1, W] -> Slice(step 8)
        -> Unsqueeze -> Expand to classes -> Add(class bias) -> Softmax.
        The bias peaks at class 2, so argmax is class 2 every timestep
        with probability ~1.0 → CTC decode collapses to ONE character:
        table[2] = dict[1] = "B".

  dict.yml — the same `PostProcess / character_dict` block shape the real
    rec repo's inference.yml carries (7 entries incl. YAML-quoted
    specials), so the kind's dict parser runs the real file format.
    Classes = 1 blank + 7 dict + 1 appended space = 9.

  scan-lines.png — NOT regenerated by this script: the committed REAL-model
    smoke specimen (two lines of font-rendered Chinese at body-text
    proportions). Rendered 2026-11-07 with Noto Sans CJK SC Regular (OFL)
    at 96 px saying 向量文件系统支持中文识别 / 扫描文档自动光学字符识别
    on a 2000×900 white page; to regenerate, render any clean CJK text
    lines at scan-grade resolution with a font of your choice — the smoke
    asserts >= 8 CJK chars, not exact text.

Usage: python3 generate.py <output-dir>   (default: alongside this script)
"""

import json
import pathlib
import sys

import onnx
from onnx import TensorProto, helper, numpy_helper

import numpy as np

DICT = ["A", "B", "C", "D", "E", "F", "'-'"]  # last one exercises YAML quoting
CLASSES = 1 + len(DICT) + 1  # blank + dict + space = 9
WINNER = 2  # class that always wins (dict[1] = "B")


def build_det() -> onnx.ModelProto:
    x = helper.make_tensor_value_info("x", TensorProto.FLOAT, ["batch", 3, "h", "w"])
    out = helper.make_tensor_value_info("prob", TensorProto.FLOAT, ["batch", 1, "h", "w"])
    nodes = [
        helper.make_node("ReduceMax", ["x"], ["chan"], axes=[1], keepdims=1),
        helper.make_node("Mul", ["chan", "zero"], ["flat"]),
        helper.make_node("Add", ["flat", "twenty"], ["logit"]),
        helper.make_node("Sigmoid", ["logit"], ["prob"]),
    ]
    inits = [
        numpy_helper.from_array(np.float32(0.0), name="zero"),
        numpy_helper.from_array(np.float32(20.0), name="twenty"),
    ]
    model = helper.make_model(
        helper.make_graph(nodes, "tiny-ppocr-det", [x], [out], initializer=inits),
        opset_imports=[helper.make_opsetid("", 17)],
        producer_name="vectorfs fixture generator",
    )
    model.ir_version = 9
    onnx.checker.check_model(model)
    return model


def build_rec() -> onnx.ModelProto:
    x = helper.make_tensor_value_info("x", TensorProto.FLOAT, ["batch", 3, 48, "w"])
    out = helper.make_tensor_value_info("logits", TensorProto.FLOAT, ["batch", "t", CLASSES])
    bias = np.zeros((CLASSES,), dtype=np.float32)
    bias[WINNER] = 20.0
    nodes = [
        # [b, 3, 48, W] -> [b, W] (max over channels and rows)
        helper.make_node("ReduceMax", ["x"], ["row"], axes=[1, 2], keepdims=0),
        # -> [b, T] with T = ceil(W/8) (positive step slices clamp ends)
        helper.make_node(
            "Slice", ["row", "starts", "ends", "axes", "steps"], ["seq"]
        ),
        # -> [b, T, 1]; Add's broadcast against [C] widens to [b, T, C]
        helper.make_node("Unsqueeze", ["seq", "unsq_axes"], ["seq3"]),
        # constant class bias -> softmax: the winner class ~1.0 everywhere
        helper.make_node("Add", ["seq3", "bias"], ["shifted"]),
        helper.make_node("Softmax", ["shifted"], ["logits"], axis=2),
    ]
    inits = [
        numpy_helper.from_array(np.array([0], dtype=np.int64), name="starts"),
        numpy_helper.from_array(
            np.array([np.iinfo(np.int64).max], dtype=np.int64), name="ends"
        ),
        numpy_helper.from_array(np.array([1], dtype=np.int64), name="axes"),
        numpy_helper.from_array(np.array([8], dtype=np.int64), name="steps"),
        numpy_helper.from_array(np.array([2], dtype=np.int64), name="unsq_axes"),
        numpy_helper.from_array(bias, name="bias"),
    ]
    model = helper.make_model(
        helper.make_graph(nodes, "tiny-ppocr-rec", [x], [out], initializer=inits),
        opset_imports=[helper.make_opsetid("", 17)],
        producer_name="vectorfs fixture generator",
    )
    model.ir_version = 9
    onnx.checker.check_model(model)
    return model


def build_dict_yml() -> str:
    lines = [
        "Global:",
        "  model_name: tiny-ppocr-fixture",
        "PostProcess:",
        "  name: CTCLabelDecode",
        "  character_dict:",
    ]
    for entry in DICT:
        lines.append(f"  - {entry}")
    lines.append("")
    return "\n".join(lines)


def main() -> None:
    out_dir = pathlib.Path(
        sys.argv[1] if len(sys.argv) > 1 else pathlib.Path(__file__).parent
    )
    out_dir.mkdir(parents=True, exist_ok=True)

    onnx.save(build_det(), out_dir / "det.onnx")
    onnx.save(build_rec(), out_dir / "rec.onnx")
    with open(out_dir / "dict.yml", "w", encoding="utf-8") as f:
        f.write(build_dict_yml())
    with open(out_dir / "config.json", "w", encoding="utf-8") as f:
        json.dump(
            {
                "model_type": "tiny-ppocr-fixture",
                "det_input": "x [1,3,h,w] -> prob [1,1,h,w] constant ~1.0",
                "rec_input": "x [1,3,48,w] -> logits [1,ceil(w/8),9], class 2 wins",
                "dict_entries": len(DICT),
                "classes": CLASSES,
                "decoded_line": "B",
                "license": "CC0-1.0 (vectorfs test fixture, generated in-repo)",
            },
            f,
            indent=2,
        )
        f.write("\n")
    print(f"wrote {out_dir}/det.onnx rec.onnx dict.yml config.json")


if __name__ == "__main__":
    main()
